{"code":"# independent verification via polynomial kernel exponentiation mod x^23-1 over F17
import json
syms=list('ABCDEFGHIJKLMNOPQ')
with open('table.json') as f: table=json.load(f)
start='BMGNGKDMPEABGNMNIMLDDDL'
O={'A':2,'B':5,'C':10,'D':9,'E':4,'F':16,'G':13,'H':6,'I':3,'J':7,'K':15,'L':8,'M':14,'N':12,'O':11,'P':0,'Q':1}
invO={v:k for k,v in O.items()}
mod=17; n=23; s=8
z=[(O[ch]-s)%mod for ch in start]
# kernel k where new[i]=sum_j ker[(i-j)%n]*old[j]
ker=[0]*n
ker[1]=15   # old[i-1] => j=i-1 => i-j=1
ker[0]=12
ker[-1% n]=14 # old[i+1] => i-j=-1 mod n

def conv(a,b):
    n=len(a)
    c=[0]*n
    for i,ai in enumerate(a):
        if ai:
            for j,bj in enumerate(b):
                if bj:
                    c[(i+j)%n]=(c[(i+j)%n]+ai*bj)%mod
    return c

def apply(ker,v):
    n=len(v)
    res=[0]*n
    for d,kv in enumerate(ker):
        if kv:
            for j,vj in enumerate(v):
                if vj:
                    res[(j+d)%n]=(res[(j+d)%n]+kv*vj)%mod
    return res
exp=10**18
kpow=ker[:]
v=z[:]
while exp>0:
    if exp&1:
        v=apply(kpow,v)
    exp//=2
    if exp:
        kpow=conv(kpow,kpow)
final=''.join(invO[(x+s)%mod] for x in v)
print(final)
print([final[i] for i in [7,9,11,15,19,22]])
# compute period of operator on vector maybe by exponent order through repeated powers? Use Floyd on vector starting from z.
# But perhaps large. Instead just maybe verify T^e via two methods for random e.
for e in [0,1,2,3,5,17,12345,10**6+3]:
    # direct binary on kernel and compare to iterative for small e<=20
    exp=e; kpow=ker[:]; v2=z[:]
    while exp>0:
        if exp&1: v2=apply(kpow,v2)
        exp//=2
        if exp: kpow=conv(kpow,kpow)
    if e<=20:
        vv=z[:]
        for _ in range(e): vv=apply(ker,vv)
        assert vv==v2
print('ok')
